<template>
  <view class="wrap">
    <!-- 余额区域 -->
    <view class="balance-box">
      <view class="yuan-icon">¥</view>
      <text class="title">我的余额</text>
      <text class="money">¥{{ userBalance }}.00</text>
    </view>

    <!-- 充值金额选择 -->
    <view class="select-box">
      <text class="label">充值</text>
      <view class="money-list">
        <view 
          v-for="item in moneyArr" 
          :key="item"
          class="money-item"
          :class="{active: selectNum === item}"
          @click="selectNum = item"
        >
          {{ item }}元
        </view>
      </view>
    </view>

    <!-- 底部充值按钮 -->
    <button class="pay-btn" @click="submitPay">充值</button>
    <view class="detail-tip" @click="goDetail">查看明细</view>
  </view>
</template>

<script>
export default {
  data() {
    return {
      // 无缓存时默认余额0
      userBalance: uni.getStorageSync('userBalance') || 0,
      selectNum: 10,
      moneyArr: [10,20,50,100,200,500]
    }
  },
  methods: {
    submitPay() {
      if (!this.selectNum) {
        uni.showToast({ title: "请选择充值金额", icon: "none" })
        return
      }
      this.userBalance += this.selectNum
      uni.showToast({ title: `充值${this.selectNum}元成功` })
      // 保存最新余额
      uni.setStorageSync('userBalance', this.userBalance)
  
      // 生成充值明细
      let now = new Date()
      let timeStr = `${now.getMonth()+1 <10 ? '0'+(now.getMonth()+1) : now.getMonth()+1}-${now.getDate() <10 ? '0'+now.getDate() : now.getDate()} ${now.getHours()}:${now.getMinutes()}`
      let newRecord = {
        id: Date.now(),
        time: timeStr,
        name: "充值中心",
        num: this.selectNum,
        type: "add"
      }
      let oldList = uni.getStorageSync('detailList') || []
      oldList.unshift(newRecord)
      uni.setStorageSync('detailList', oldList)
    },
    goDetail() {
      uni.navigateTo({
        url: "/pages/changeDetail/changeDetail"
      })
    }
  }
}
</script>

